 for(int i=0;i<3;i++)if(Distance(player.Position,new Vector3((float)ExpeditionDungeon.ChestX[i],0,(float)ExpeditionDungeon.ChestZ[i]))<2.5){if(Guarded(ExpeditionDungeon.ChestX[i],ExpeditionDungeon.ChestZ[i],8)){game.Notice="Chest guarded / clear nearby infected";return;}var relic=ExpeditionRelic.Roll(game.Save.Seed,dungeon,i);if(game.Profile.Claimed.Contains(relic.Id)){game.Notice="Chest empty";return;}game.Change(()=>{game.Profile.Claim(relic);game.AwardResearch("discovery/dungeon/"+dungeon.Id,25);});game.Notice="Found "+relic.Name+" / tier "+relic.Level;return;}ReadDungeonRecord();return;}
 foreach(var w in game.World.Changes.Wells)if(ExpeditionGame.Distance(player.Position.X,player.Position.Z,w.X,w.Z)<2.3){game.Change(()=>game.Craft.Water++);game.Notice="Collected water / C to drink";return;}
